import{_ as t,o as a,c as r,a6 as n}from"./chunks/framework.DIp0zHSV.js";const m=JSON.parse('{"title":"Core Subsystems","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/subsystems/index.md","filePath":"architecture/subsystems/index.md","lastUpdated":1791165399000}'),s={name:"architecture/subsystems/index.md"};function o(i,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="core-subsystems" tabindex="-1">Core Subsystems <a class="header-anchor" href="#core-subsystems" aria-label="Permalink to &quot;Core Subsystems&quot;">​</a></h1><p>LCARdS exposes a set of singleton services on <code>window.lcards.core.*</code>, all instantiated by <code>LCARdSCore._performInitialization()</code>. Most extend <code>BaseService</code> and receive HASS updates via <code>LCARdSCore.ingestHass()</code>; a handful (<code>componentManager</code>, <code>stylePresetManager</code>, <code>packManager</code>, <code>systemsManager</code>, <code>validationService</code>) are plain classes that don&#39;t need HASS directly. Cards never instantiate subsystems directly.</p><hr><h2 id="quick-reference" tabindex="-1">Quick Reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Subsystem</th><th>Singleton</th><th>Role</th></tr></thead><tbody><tr><td><a href="#animation-manager">Animation Manager</a></td><td><code>animationManager</code></td><td>anime.js v4 orchestration, scoped per overlay</td></tr><tr><td><a href="#asset-manager">Asset Manager</a></td><td><code>assetManager</code></td><td>SVG / font / audio loading and caching</td></tr><tr><td><a href="#component-manager">Component Manager</a></td><td><code>componentManager</code></td><td>Named multi-segment SVG component registry</td></tr><tr><td><a href="#connection-overlay">Connection Overlay</a></td><td><code>connectionOverlayService</code></td><td>Full-screen lost-connection UI</td></tr><tr><td><a href="#datasource-system">DataSource System</a></td><td><code>dataSourceManager</code></td><td>Rolling entity buffers with processor pipelines</td></tr><tr><td><a href="#device-identity">Device Identity</a></td><td><code>deviceIdentityManager</code></td><td>Stable per-browser UUID for scoped settings</td></tr><tr><td><a href="#helper-manager">Helper Manager</a></td><td><code>helperManager</code></td><td>HA input_* helper read/write</td></tr><tr><td><a href="#integration-service">Integration Service</a></td><td><code>integrationService</code></td><td>Backend probe, storage helpers, push events</td></tr><tr><td><a href="#pack-system">Pack System</a></td><td><code>packManager</code></td><td>Named bundles: themes, components, presets, assets</td></tr><tr><td><a href="#rules-engine">Rules Engine</a></td><td><code>rulesManager</code></td><td>Condition evaluation → style patch on overlays</td></tr><tr><td><a href="#scoped-settings">Scoped Settings</a></td><td><code>scopedSettingsService</code></td><td>Device → user → global three-tier waterfall</td></tr><tr><td><a href="#screen-effect-system">Screen Effect System</a></td><td><code>screenEffectManager</code></td><td>Full-screen composited canvas effects</td></tr><tr><td><a href="#sound-system">Sound System</a></td><td><code>soundManager</code></td><td>Event-driven audio with scheme mapping</td></tr><tr><td><a href="#style-preset-manager">Style Preset Manager</a></td><td><code>stylePresetManager</code></td><td>Named preset bundles loaded from packs</td></tr><tr><td><a href="#systems-manager">Systems Manager</a></td><td><code>systemsManager</code></td><td>Entity state cache, subscriptions, overlay registry</td></tr><tr><td><a href="#template-system">Template System</a></td><td><em>(no singleton: instantiated per use)</em></td><td>Unified evaluator for all four template types</td></tr><tr><td><a href="#theme-system">Theme System</a></td><td><code>themeManager</code></td><td>Token resolution, alert palette transforms</td></tr><tr><td><a href="#validation-service">Validation Service</a></td><td><code>validationService</code></td><td>Runtime config schema validation by card type</td></tr></tbody></table><hr><h2 id="animation-manager" tabindex="-1">Animation Manager <a class="header-anchor" href="#animation-manager" aria-label="Permalink to &quot;Animation Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.animationManager</code></strong> · <a href="./animation-manager.html">Full reference →</a></p><p>Orchestrates anime.js v4 animations scoped per overlay. Integrates with DataSource thresholds and the Rules Engine for reactive and rule-triggered playback. Maintains an <code>AnimationRegistry</code> that caches animation instances for performance.</p><p>Consult this when implementing card animations, wiring entity-change or datasource triggers, or using built-in presets like <code>pulse</code> and <code>slide</code>.</p><hr><h2 id="asset-manager" tabindex="-1">Asset Manager <a class="header-anchor" href="#asset-manager" aria-label="Permalink to &quot;Asset Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.assetManager</code></strong> · <a href="./asset-manager.html">Full reference →</a></p><p>Loads and caches SVG, font, and audio assets from packs, keeping a URL-only registry for browser-native image loading. Provides runtime registration of user images as first-class builtin references.</p><p>Consult this when adding custom assets to cards, registering user images, or loading SVG/font content at runtime.</p><hr><h2 id="component-manager" tabindex="-1">Component Manager <a class="header-anchor" href="#component-manager" aria-label="Permalink to &quot;Component Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.componentManager</code></strong> · <a href="./component-manager.html">Full reference →</a></p><p>Holds named SVG component definitions (dpad, alert, elbow variants) where each segment can receive independent styling and actions. Consumed by button cards running in component mode.</p><p>Consult this when building multi-segment interactive shapes or defining new component types.</p><hr><h2 id="connection-overlay" tabindex="-1">Connection Overlay <a class="header-anchor" href="#connection-overlay" aria-label="Permalink to &quot;Connection Overlay&quot;">​</a></h2><p><strong><code>window.lcards.core.connectionOverlayService</code></strong> · <a href="./connection-overlay.html">Full reference →</a></p><p>Monitors the Home Assistant WebSocket connection and renders a full-screen overlay when the frontend loses server contact. Supports text or custom card modes and optional reconnection banners, configured via the scoped settings waterfall.</p><p>Consult this when customising connection-lost behaviour or layering it with <code>ScreenEffectManager</code>.</p><hr><h2 id="datasource-system" tabindex="-1">DataSource System <a class="header-anchor" href="#datasource-system" aria-label="Permalink to &quot;DataSource System&quot;">​</a></h2><p><strong><code>window.lcards.core.dataSourceManager</code></strong> · <a href="./datasource-system.html">Full reference →</a></p><p>Manages named entity data buffers with rolling history and processor pipelines (unit conversion, smoothing, trending, statistics). Provides reactive subscriptions so cards receive processed values automatically on entity change.</p><p>Consult this when cards need derived sensor data, statistics-based displays, or datasource-threshold-driven animations.</p><hr><h2 id="device-identity" tabindex="-1">Device Identity <a class="header-anchor" href="#device-identity" aria-label="Permalink to &quot;Device Identity&quot;">​</a></h2><p><strong><code>window.lcards.core.deviceIdentityManager</code></strong> · <a href="./device-identity.html">Full reference →</a></p><p>Provides a stable browser-profile identity using a stored UUID and auto-seeded display name. This identity is the key for device-scoped settings in the ScopedSettingsService waterfall.</p><p>Consult this when implementing per-device configuration or device-specific features like kiosk overrides.</p><hr><h2 id="helper-manager" tabindex="-1">Helper Manager <a class="header-anchor" href="#helper-manager" aria-label="Permalink to &quot;Helper Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.helperManager</code></strong> · <a href="./helper-manager.html">Full reference →</a></p><p>Manages HA <code>input_*</code> helper entities (select, boolean, number) for persistent frontend state: alert mode, sound schemes, user preferences. Provides typed read/write access and auto-creation of missing helpers.</p><p>Consult this when implementing features that need HA-backed persistent storage or when reading/writing alert and sound configuration.</p><hr><h2 id="integration-service" tabindex="-1">Integration Service <a class="header-anchor" href="#integration-service" aria-label="Permalink to &quot;Integration Service&quot;">​</a></h2><p><strong><code>window.lcards.core.integrationService</code></strong> · <a href="./integration-service.html">Full reference →</a></p><p>Probes the LCARdS HA backend on startup to determine availability, wraps WebSocket storage operations, and handles push events from Python service handlers (reload, log level, portal overlays).</p><p>Consult this when implementing backend-dependent features, checking integration availability before persisting data, or handling remote-control directives.</p><hr><h2 id="pack-system" tabindex="-1">Pack System <a class="header-anchor" href="#pack-system" aria-label="Permalink to &quot;Pack System&quot;">​</a></h2><p><strong><code>window.lcards.core.packManager</code></strong> · <a href="./pack-system.html">Full reference →</a></p><p>Defines the structure, loading, and distribution of named bundles containing style presets, components, themes, rules, animations, and assets. Packs are loaded at startup by <code>PackManager</code>; downstream registries consume the declared entries.</p><p>Consult this when creating new packs, adding component types, or understanding how registries populate from pack data.</p><hr><h2 id="rules-engine" tabindex="-1">Rules Engine <a class="header-anchor" href="#rules-engine" aria-label="Permalink to &quot;Rules Engine&quot;">​</a></h2><p><strong><code>window.lcards.core.rulesManager</code></strong> · <a href="./rules-engine.html">Full reference →</a></p><p>Evaluates rule conditions on every HASS state push and produces style patches that are merged onto target overlays; overlays have no knowledge that a rule is driving them. Supports complex multi-condition logic and cross-card overlay targeting by tag, type, ID, or pattern.</p><p>Consult this when implementing conditional styling, state-dependent animations, or coordinated alert patterns across multiple cards.</p><hr><h2 id="scoped-settings" tabindex="-1">Scoped Settings <a class="header-anchor" href="#scoped-settings" aria-label="Permalink to &quot;Scoped Settings&quot;">​</a></h2><p><strong><code>window.lcards.core.scopedSettingsService</code></strong> · <a href="./scoped-settings.html">Full reference →</a></p><p>Implements a three-tier waterfall (device → user → global) for any LCARdS setting. Each scope can be overridden independently; the most-specific set value wins at read time, and all scopes are persisted to the HA backend.</p><p>Consult this when adding new settings that need per-device or per-user overrides.</p><hr><h2 id="screen-effect-system" tabindex="-1">Screen Effect System <a class="header-anchor" href="#screen-effect-system" aria-label="Permalink to &quot;Screen Effect System&quot;">​</a></h2><p><strong><code>window.lcards.core.screenEffectManager</code></strong> · <a href="./screen-effects.html">Full reference →</a></p><p>Composites a full-screen canvas effect layer above all UI. Ships named presets (blur, static, pixelate, glitch, vignette) accessible via console API, HA services, and card config. Layered above <code>ConnectionOverlay</code>.</p><p>Consult this when implementing visual feedback, alert backdrop effects, or custom canvas-based screen effects.</p><hr><h2 id="sound-system" tabindex="-1">Sound System <a class="header-anchor" href="#sound-system" aria-label="Permalink to &quot;Sound System&quot;">​</a></h2><p><strong><code>window.lcards.core.soundManager</code></strong> · <a href="./sound-system.html">Full reference →</a></p><p>Event-driven audio feedback for card interactions and HA UI events. Maps events to assets via schemes defined in packs, with per-event overrides and scoped settings support for per-user and per-device sound preferences.</p><p>Consult this when playing sounds on card actions, configuring sound schemes via packs, or implementing per-user/device audio preferences.</p><hr><h2 id="style-preset-manager" tabindex="-1">Style Preset Manager <a class="header-anchor" href="#style-preset-manager" aria-label="Permalink to &quot;Style Preset Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.stylePresetManager</code></strong> · <a href="./style-preset-manager.html">Full reference →</a></p><p>Stores named preset objects (lozenge, bullet, pills, gauge, etc.) loaded from packs. Cards reference presets by name to avoid hard-coding style definitions, and the manager resolves the full preset object at render time.</p><p>Consult this when creating card style presets or when cards need to look up and apply style bundles by name.</p><hr><h2 id="systems-manager" tabindex="-1">Systems Manager <a class="header-anchor" href="#systems-manager" aria-label="Permalink to &quot;Systems Manager&quot;">​</a></h2><p><strong><code>window.lcards.core.systemsManager</code></strong> · <a href="./systems-manager.html">Full reference →</a></p><p>Provides the shared entity state cache with targeted subscriptions and change deduplication for all LCARdS cards, plus an overlay registry used by the Rules Engine for cross-card targeting.</p><p>Consult this when cards need entity state subscriptions, when registering overlays for rule targeting, or performing overlay-aware operations.</p><hr><h2 id="template-system" tabindex="-1">Template System <a class="header-anchor" href="#template-system" aria-label="Permalink to &quot;Template System&quot;">​</a></h2><p><strong><code>new UnifiedTemplateEvaluator(...)</code></strong>: not a core singleton; cards instantiate one directly · <a href="./template-system.html">Full reference →</a></p><p>Unified evaluator for all four LCARdS template types (JavaScript <code>[[[...]]]</code>, LCARdS tokens <code>{...}</code>, DataSource references <code>{ds:...}</code>, and Jinja2 <code>{{...}}</code>) applied in a fixed priority order via <code>UnifiedTemplateEvaluator</code>.</p><p>Consult this when implementing dynamic text fields, understanding template evaluation order, or injecting custom context into expressions.</p><hr><h2 id="theme-system" tabindex="-1">Theme System <a class="header-anchor" href="#theme-system" aria-label="Permalink to &quot;Theme System&quot;">​</a></h2><p><strong><code>window.lcards.core.themeManager</code></strong> · <a href="./theme-system.html">Full reference →</a></p><p>Token-based theming with alert-mode palette transformations. Maintains the active theme registry and resolves <code>theme:</code> token paths to concrete CSS values. The resolver singleton (<code>themeManager.resolver</code>) must be accessed via <code>window.lcards.core</code>; module-level imports have no token tree.</p><p>Consult this when implementing theme-aware styling, accessing theme tokens in code or config, or supporting alert-triggered palette swaps.</p><hr><h2 id="validation-service" tabindex="-1">Validation Service <a class="header-anchor" href="#validation-service" aria-label="Permalink to &quot;Validation Service&quot;">​</a></h2><p><strong><code>window.lcards.core.validationService</code></strong> · <a href="./validation-service.html">Full reference →</a></p><p>Runtime config schema validation keyed by card type. Catches structural errors and unknown fields before render and surfaces them in the editor. Card schemas are registered in <code>CoreConfigManager</code>.</p><p>Consult this when implementing card config validation, understanding error reporting paths, or debugging configuration issues in the editor.</p>',95)])])}const g=t(s,[["render",o]]);export{m as __pageData,g as default};
